<script setup>
import {ref,onMounted} from 'vue'
const config={"id":"babaquna","name":"爸爸去哪","icon":"/icons/babaquna.png","color":"#1677ff","primary":"book","primaryLabel":"预订"}
const ready=ref(false),error=ref(''),items=ref([]),revision=ref(0),message=ref('')
const api=(url,method='GET',data)=>new Promise((resolve,reject)=>uni.request({url:'http://127.0.0.1:8080'+url,method,data,header:{'Content-Type':'application/json'},success:r=>r.statusCode<400?resolve(r.data):reject(new Error(r.data?.error?.code||'HTTP_'+r.statusCode)),fail:reject}))
const load=async()=>{try{const boot=await api('/runtime/v1/apps/'+config.id+'/bootstrap');revision.value=boot.initial_state_ref.revision;const page=await api('/runtime/v1/apps/'+config.id+'/data/'+boot.dataset.resources[0]+'?limit=20');items.value=page.items;ready.value=true}catch(e){error.value=e.message}}
const act=async item=>{try{const result=await api('/runtime/v1/apps/'+config.id+'/actions','POST',{action_id:Date.now()+'-'+Math.random(),type:config.primary,payload:{item_id:item.id,expected_price:item.price},expected_revision:revision.value});revision.value=result.revision;message.value=result.result.message}catch(e){error.value=e.message}}
onMounted(load)
</script>
<template><view class="page" :style="{'--brand':config.color}"><view class="header"><image class="icon" :src="config.icon" mode="aspectFill"/><view><text class="title">{{config.name}}</text><text class="sub">Uni-app 离线构建</text></view><text class="ready">{{ready?'已就绪':'加载中'}}</text></view><view v-if="error" class="error" @click="load">{{error}} · 点击重试</view><view v-if="message" class="toast">{{message}}</view><view v-for="item in items" :key="item.id" class="item"><view><text class="name">{{item.title}}</text><text class="meta">¥{{item.price}} · 余量 {{item.available}}</text></view><button size="mini" @click="act(item)">{{config.primaryLabel}}</button></view></view></template>
<style>.page{min-height:100vh;background:#f6f7f9;padding:24rpx}.header,.item{display:flex;align-items:center;background:#fff;padding:24rpx;border-radius:20rpx;margin-bottom:16rpx}.icon{width:64rpx;height:64rpx;border-radius:16rpx;margin-right:18rpx}.title,.name{display:block;font-weight:700}.sub,.meta{display:block;color:#888;font-size:22rpx;margin-top:8rpx}.ready{margin-left:auto;color:#17874b}.item{justify-content:space-between}.item button{background:var(--brand);color:#fff}.error{background:#fff0f0;color:#a00;padding:20rpx;margin-bottom:16rpx}.toast{position:fixed;z-index:2;bottom:80rpx;left:30%;right:30%;background:#222;color:#fff;text-align:center;padding:18rpx;border-radius:30rpx}</style>
